        "priority": "high",
        "status": "completed",
        "due": "Today"
    },
    {
        "id": 2,
        "title": "Implement REST Endpoints",
        "priority": "urgent",
        "status": "in_progress",
        "due": "Tomorrow"
    },
    {
        "id": 3,
        "title": "Write Integration Test Suite",
        "priority": "medium",
        "status": "pending",
        "due": "Friday"
    }
]);
